window.products.push({"id":712519,"name":"Mr. Heater 30,000 BTU Natural Gas Radiant Vent Free Heater #VF30KRADNG","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/91MQFUFvHIL._AC_SL1500_.jpg","description":"The Mr. Heater Vent Free Blue Flame Natural Gas Heater. Quick, quiet convection heat! Convenient, easy and safe! Not to mention economical and efficient. It's just the ticket when you need to kill the chill in your ice house, cabin, enclosed porch or that drafty room in your house. No venting or chimney required. Features a thermostat for easy temp control and a quiet integrated blower for gentle circulation of warm, comfortable air. Oxygen depletion sensors, a battery-operated electronic ignition for a quick start. 30,000 BTU model: Heats up to 1,000 sq. ft..","images":["https://m.media-amazon.com/images/I/91MQFUFvHIL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Mr. Heater","source_asin":"B000UPSL74","category_path":"Home & Kitchen"},"sku":"BM-712519","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B000UPSL74","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B000UPSL74","price_pending":true,"merchant_ready":false});
