window.products.push({"id":712573,"name":"Wusthof Gourmet - 6 Pc. Steak Knife Knife Set with Custom Engraving","category":"homeandappliances","retail price":200.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61O1zO7IjrL._AC_SL1400_.jpg","description":"Chef's Arsenal is proud to offer authentic \"Rotary Engraving\" of this best-selling Wusthof Gourmet 6 Pc. Steak Knife Set. This is different, and superior to \"Laser Engraving\". Lasers can not directly engrave pure steel, so Laser engraved knives must be treated first with a chemical before \"marking\". The resulting \"marking\" by a laser is flat, and black, and will wear off with time. Our engraving is etched directly into the steel, creating a everlasting heirloom, with your choice of text.","images":["https://m.media-amazon.com/images/I/61O1zO7IjrL._AC_SL1400_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Wüsthof","source_asin":"B07NJLJRD9","category_path":"Home & Kitchen"},"sku":"BM-712573","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07NJLJRD9","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07NJLJRD9","price_pending":true,"merchant_ready":false});
